fn solve(input: Vec<char>) -> Vec<char> {
    // Copy input so we can modify it
    let mut v = input;

    // Step 1: If the last character is '\n', remove it.
    if let Some(&'\n') = v.last() {
        v.pop();
    }

    // Helper to identify our whitespace set
    fn is_ws(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    // Step 2: Find trim boundaries
    // `start` = first index from the left that is not whitespace
    let start = v.iter()
                 .position(|&c| !is_ws(c))
                 .unwrap_or(v.len());
    // `end` = last index from the right that is not whitespace
    let end_opt = v.iter()
                   .rposition(|&c| !is_ws(c));

    // Get a slice of the trimmed data
    let trimmed: &[char] = if let Some(end) = end_opt {
        if start <= end {
            &v[start..=end]
        } else {
            &[]
        }
    } else {
        &[]
    };

    // Step 3: Check password validity
    let len = trimmed.len();
    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_digit = false;

    for &c in trimmed {
        if c.is_ascii_lowercase() {
            has_lower = true;
        } else if c.is_ascii_uppercase() {
            has_upper = true;
        } else if c.is_ascii_digit() {
            has_digit = true;
        }
    }

    // Step 4: Prepare result
    let result_str = if len >= 5 && has_lower && has_upper && has_digit {
        "Correct\n"
    } else {
        "Too weak\n"
    };

    // Convert the result string into Vec<char>
    result_str.chars().collect()
}